package com.threatstream.detection;
import org.apache.kafka.common.TopicPartition; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.DeadLetterPublishingRecoverer; import org.springframework.kafka.listener.DefaultErrorHandler; import org.springframework.util.backoff.FixedBackOff;
@Configuration class KafkaErrorConfiguration { @Bean DefaultErrorHandler kafkaErrorHandler(KafkaTemplate<Object,Object> template, DetectionProperties p){var recoverer=new DeadLetterPublishingRecoverer(template,(record,error)->new TopicPartition(p.dltTopic(),record.partition()));return new DefaultErrorHandler(recoverer,new FixedBackOff(1000L,p.retryAttempts()));} }
